const std = @import("std");
const C = @import("canvas.zig");
const P = @import("primitives.zig");
const F = @import("fill.zig");
const K = @import("clipping.zig");
const W = @import("ppm_writer.zig");
const Tag = enum { LINE, RECT, FILLRECT, CIRCLE, FILLCIRCLE, ELLIPSE, FILLELLIPSE, POLYLINE, POLYGON, FILLPOLYGON, PATH, FILLPATH, FLOOD, TEXT, ERASE, TRANSLATE, SCALE, ROTATE, SAVE, RESTORE, CLIP, NOCLIP, USE };
const ErrorName = enum { unknown_command, bad_arguments, unknown_style, unknown_symbol, unknown_glyph, bad_value, stack_empty };
const Pen = struct { width: i64, color: []const u8, on: i64, off: i64 };
const Axis = enum { x, y };
const Brush = struct { colors: C.Strings, axis: ?Axis, rule: C.Rule };
const Styles = struct { colors: std.StringHashMapUnmanaged(C.Color) = .empty, pens: std.StringHashMapUnmanaged(Pen) = .empty, brushes: std.StringHashMapUnmanaged(Brush) = .empty };
const Font = struct { width: i64, height: i64, glyphs: std.AutoHashMapUnmanaged(u8, []const C.Point) = .empty };
const Command = struct { line: usize, keyword: []const u8, args: C.Strings };
const Item = union(enum) { command: *Command, repetition: *Repetition };
const Repetition = struct { count: usize, dx: i64, dy: i64, body: std.ArrayList(Item) = .empty };
const Block = struct { name: []const u8, opacity: i64 = 0, mode: C.Mode = .normal, body: std.ArrayList(Item) = .empty, end_line: usize = 0 };
const Scene = struct { width: usize = 0, height: usize = 0, background: []const u8 = "", layers: std.ArrayList(*Block) = .empty, symbols: std.StringHashMapUnmanaged(*Block) = .empty };
const Probe = struct { point: bool, values: []const i64 };
const PathCommand = struct { letter: u8, values: [6]i64 = [_]i64{0} ** 6, count: usize };
const Subpath = struct { points: std.ArrayList(C.Point) = .empty, closed: bool = false };
const Execution = struct { sequence: usize, layer: usize, command: *const Command, kind: enum { drawing, state, failed } = .state, failure: ?ErrorName = null, pixels: usize = 0, box: ?C.Rect = null };
const Pair = struct { matrix: [6]i64, clip: C.Rect };
const Snapshot = struct { matrix: [6]i64, clip: C.Rect, stack: []const Pair };
const State = struct {
    matrix: [6]i64 = .{ 1, 0, 0, 1, 0, 0 }, clip: C.Rect, stack: std.ArrayList(Pair) = .empty,
    fn snapshot(self: *const State) Snapshot { return .{ .matrix = self.matrix, .clip = self.clip, .stack = C.backing.dupe(Pair, self.stack.items) catch @panic("allocation failed") }; }
    fn rollback(self: *State, saved: Snapshot) void { self.matrix = saved.matrix; self.clip = saved.clip; self.stack.items.len = 0; self.stack.appendSlice(C.allocator, saved.stack) catch @panic("allocation failed"); }
    fn point(self: *const State, x: i64, y: i64) C.Point { const m = self.matrix; return .{ .x = m[0] * x + m[1] * y + m[4], .y = m[2] * x + m[3] * y + m[5] }; }
    fn rectangle(self: *const State, values: []const i64) C.Rect { const first = self.point(values[0], values[1]); const last = self.point(values[2], values[3]); return .{ .x0 = @min(first.x, last.x), .y0 = @min(first.y, last.y), .x1 = @max(first.x, last.x), .y1 = @max(first.y, last.y) }; }
    fn radii(self: *const State, rx: i64, ry: i64) C.Point { const m = self.matrix; return .{ .x = C.abs(m[0]) * rx + C.abs(m[1]) * ry, .y = C.abs(m[2]) * rx + C.abs(m[3]) * ry }; }
    fn translate(self: *State, dx: i64, dy: i64) void { self.matrix[4] += self.matrix[0] * dx + self.matrix[1] * dy; self.matrix[5] += self.matrix[2] * dx + self.matrix[3] * dy; }
};
fn enumValue(comptime T: type, name: []const u8) ?T { inline for (@typeInfo(T).@"enum".field_names) |candidate| { if (C.eq(candidate, name)) return @field(T, candidate); } return null; }
fn upper(ch: u8) u8 { return if (ch >= 'a' and ch <= 'z') ch - 32 else ch; }
fn integer(word: []const u8) bool { if (word.len == 0) return false; const digits = if (word[0] == '-') word[1..] else word; if (digits.len == 0) return false; for (digits) |ch| { if (ch < '0' or ch > '9') return false; } return true; }
fn allIntegers(words: C.Strings) bool { for (words) |word| { if (!integer(word)) return false; } return true; }
fn numbers(words: C.Strings) []const i64 { const result = C.tempAlloc(i64, words.len); for (words, result) |word, *value| value.* = C.number(word); return result; }
fn permanentNumbers(words: C.Strings) []const i64 { const result = C.alloc(i64, words.len); for (words, result) |word, *value| value.* = C.number(word); return result; }
fn penCommand(tag: Tag) bool { return switch (tag) { .LINE, .RECT, .CIRCLE, .ELLIPSE, .POLYLINE, .POLYGON, .PATH => true, else => false }; }
fn brushCommand(tag: Tag) bool { return switch (tag) { .FILLRECT, .FILLCIRCLE, .FILLELLIPSE, .FILLPOLYGON, .FILLPATH, .FLOOD, .TEXT => true, else => false }; }
fn stateCommand(tag: Tag) bool { return @intFromEnum(tag) >= @intFromEnum(Tag.TRANSLATE); }
fn arity(letter: u8) ?usize { return switch (upper(letter)) { 'M', 'L' => 2, 'H', 'V' => 1, 'Q' => 4, 'C' => 6, 'Z' => 0, else => null }; }
fn parsePath(words: C.Strings) ?[]const PathCommand { var result: std.ArrayList(PathCommand) = .empty; var index: usize = 0; var starts = true; while (index < words.len) { if (words[index].len != 1) return null; const letter = words[index][0]; const count = arity(letter) orelse return null; if (index + count >= words.len or !allIntegers(words[index + 1..index + 1 + count])) return null; if (starts and upper(letter) != 'M') return null; var command: PathCommand = .{ .letter = letter, .count = count }; for (words[index + 1..index + 1 + count], 0..) |word, i| command.values[i] = C.number(word); C.push(PathCommand, &result, command); starts = upper(letter) == 'Z'; index += count + 1; } return if (result.items.len == 0) null else result.items; }
fn validForm(tag: Tag, args: C.Strings) bool { const Form = struct { count: usize, first_integer: usize }; const fixed: ?Form = switch (tag) { .LINE, .RECT, .FILLRECT, .ELLIPSE, .FILLELLIPSE => .{ .count = 5, .first_integer = 1 }, .CIRCLE, .FILLCIRCLE => .{ .count = 4, .first_integer = 1 }, .FLOOD, .USE => .{ .count = 3, .first_integer = 1 }, .ERASE, .CLIP => .{ .count = 4, .first_integer = 0 }, .TRANSLATE, .SCALE => .{ .count = 2, .first_integer = 0 }, .ROTATE => .{ .count = 1, .first_integer = 0 }, .SAVE, .RESTORE, .NOCLIP => .{ .count = 0, .first_integer = 0 }, else => null };
    if (fixed) |form| return args.len == form.count and allIntegers(args[form.first_integer..]); if (tag == .TEXT) return args.len == 5 and allIntegers(args[1..3]); if (tag == .POLYLINE or tag == .POLYGON or tag == .FILLPOLYGON) return args.len >= 2 and allIntegers(args[1..]) and C.int(args.len) == 2 + 2 * C.number(args[1]); return args.len >= 2 and integer(args[1]) and parsePath(args[2..]) != null;
}
fn readStyles(text: []const u8) Styles { var result: Styles = .{}; for (C.lines(text)) |line| { if (line.len == 0 or line[0] == '#') continue; const words = C.words(line); const name = words[1]; if (C.eq(words[0], "color")) { var color: C.Color = undefined; for (words[2..], &color) |word, *value| value.* = C.number(word); result.colors.put(C.allocator, name, color) catch @panic("allocation failed"); } else if (C.eq(words[0], "pen")) { result.pens.put(C.allocator, name, .{ .width = C.number(words[2]), .color = words[3], .on = C.number(words[4]), .off = C.number(words[5]) }) catch @panic("allocation failed"); } else { const solid = C.eq(words[0], "brush"); result.brushes.put(C.allocator, name, .{ .colors = words[2..if (solid) 3 else 4], .axis = if (solid) null else enumValue(Axis, words[4]).?, .rule = enumValue(C.Rule, words[if (solid) 3 else 5]).? }) catch @panic("allocation failed"); } } return result; }
fn readFont(text: []const u8) Font { const lines = C.lines(text); const header = C.words(lines[0]); var font: Font = .{ .width = C.number(header[1]), .height = C.number(header[2]) }; var index: usize = 1; while (index < lines.len) { const ch = C.words(lines[index])[1][0]; var dots: std.ArrayList(C.Point) = .empty; for (0..C.index(font.height)) |row| { for (lines[index + row + 1], 0..) |mark, column| { if (mark == '#') C.append(C.Point, &dots, .{ .x = C.int(column), .y = C.int(row) }); } } font.glyphs.put(C.allocator, ch, dots.items) catch @panic("allocation failed"); index += C.index(font.height) + 1; } return font; }
fn readScene(text: []const u8) Scene { var result: Scene = .{}; var block: ?*Block = null; var bodies: std.ArrayList(*std.ArrayList(Item)) = .empty; for (C.lines(text), 1..) |line, number| { const words = C.words(line); if (words.len == 0 or words[0][0] == '#') continue; const key = words[0]; const args = words[1..]; if (C.eq(key, "CANVAS")) { result.width = C.index(C.number(args[0])); result.height = C.index(C.number(args[1])); result.background = args[2]; } else if (C.eq(key, "LAYER") or C.eq(key, "SYMBOL")) { block = C.create(Block, .{ .name = args[0] }); if (C.eq(key, "LAYER")) { block.?.opacity = C.number(args[1]); block.?.mode = enumValue(C.Mode, args[2]).?; C.append(*Block, &result.layers, block.?); } else result.symbols.put(C.allocator, args[0], block.?) catch @panic("allocation failed"); bodies.items.len = 0; C.append(*std.ArrayList(Item), &bodies, &block.?.body); } else if (C.eq(key, "END")) { block.?.end_line = number; bodies.items.len = 0; } else if (C.eq(key, "REPEAT")) { const repetition = C.create(Repetition, .{ .count = C.index(C.number(args[0])), .dx = C.number(args[1]), .dy = C.number(args[2]) }); C.append(Item, bodies.items[bodies.items.len - 1], .{ .repetition = repetition }); C.append(*std.ArrayList(Item), &bodies, &repetition.body); } else if (C.eq(key, "ENDREPEAT")) { _ = bodies.pop(); } else C.append(Item, bodies.items[bodies.items.len - 1], .{ .command = C.create(Command, .{ .line = number, .keyword = key, .args = args }) }); } return result; }
fn readProbes(text: []const u8) []const Probe { const lines = C.lines(text); const result = C.alloc(Probe, C.index(C.number(lines[0]))); for (lines[1..], result) |line, *probe| { const words = C.words(line); probe.* = .{ .point = C.eq(words[0], "point"), .values = permanentNumbers(words[1..]) }; } return result; }
const Renderer = struct {
    scene: *const Scene, styles: *const Styles, font: *const Font, screen: C.Rect, state: State, layers: std.ArrayList(*C.Layer) = .empty, executions: std.ArrayList(*Execution) = .empty,
    fn init(scene: *const Scene, styles: *const Styles, font: *const Font) Renderer { const screen: C.Rect = .{ .x0 = 0, .y0 = 0, .x1 = C.int(scene.width) - 1, .y1 = C.int(scene.height) - 1 }; return .{ .scene = scene, .styles = styles, .font = font, .screen = screen, .state = .{ .clip = screen } }; }
    fn layer(self: *const Renderer) *C.Layer { return self.layers.items[self.layers.items.len - 1]; }
    fn check(self: *const Renderer, command: *const Command) ?ErrorName { const tag = enumValue(Tag, command.keyword) orelse return .unknown_command; const args = command.args; if (!validForm(tag, args)) return .bad_arguments; if (penCommand(tag) and !self.styles.pens.contains(args[0])) return .unknown_style; if (brushCommand(tag) and !self.styles.brushes.contains(args[0])) return .unknown_style;
        if (tag == .USE) { const symbol = self.scene.symbols.get(args[0]) orelse return .unknown_symbol; if (symbol.end_line >= command.line) return .unknown_symbol; } if (tag == .TEXT) { for (args[4]) |ch| { if (ch != '_' and !self.font.glyphs.contains(ch)) return .unknown_glyph; } } if (tag == .RESTORE and self.state.stack.items.len == 0) return .stack_empty;
        const valid = switch (tag) { .CIRCLE, .FILLCIRCLE => C.number(args[3]) >= 1, .ELLIPSE, .FILLELLIPSE => C.number(args[3]) >= 1 and C.number(args[4]) >= 1, .POLYLINE => C.number(args[1]) >= 2, .POLYGON, .FILLPOLYGON => C.number(args[1]) >= 3, .PATH, .FILLPATH => C.number(args[1]) >= 1 and C.number(args[1]) <= 32, .FLOOD => self.state.clip.contains(self.state.point(C.number(args[1]), C.number(args[2]))), .TEXT => C.eq(args[3], "left") or C.eq(args[3], "center") or C.eq(args[3], "right"), .SCALE => C.number(args[0]) != 0 and C.number(args[1]) != 0, .CLIP => !self.state.rectangle(numbers(args)).intersect(self.state.clip).empty(), else => true }; return if (valid) null else .bad_value;
    }
    fn applyState(self: *Renderer, tag: Tag, args: C.Strings) void {
        switch (tag) {
            .TRANSLATE => self.state.translate(C.number(args[0]), C.number(args[1])),
            .SCALE => { const sx = C.number(args[0]); const sy = C.number(args[1]); self.state.matrix[0] *= sx; self.state.matrix[2] *= sx; self.state.matrix[1] *= sy; self.state.matrix[3] *= sy; },
            .ROTATE => { for (0..C.index(@mod(C.number(args[0]), 4))) |_| { const m = self.state.matrix; self.state.matrix = .{ m[1], -m[0], m[3], -m[2], m[4], m[5] }; } },
            .SAVE => C.append(Pair, &self.state.stack, .{ .matrix = self.state.matrix, .clip = self.state.clip }),
            .RESTORE => { const pair = self.state.stack.pop().?; self.state.matrix = pair.matrix; self.state.clip = pair.clip; },
            .CLIP => self.state.clip = self.state.rectangle(numbers(args)).intersect(self.state.clip), .NOCLIP => self.state.clip = self.screen,
            .USE => { const saved = self.state.snapshot(); defer C.backing.free(saved.stack); self.state.translate(C.number(args[1]), C.number(args[2])); self.executeBody(self.scene.symbols.get(args[0]).?.body.items); self.state.rollback(saved); },
            else => unreachable,
        }
    }
    fn executeBody(self: *Renderer, body: []const Item) void { for (body) |item| { switch (item) { .command => |command| self.executeCommand(command), .repetition => |repetition| { const saved = self.state.snapshot(); defer C.backing.free(saved.stack); for (0..repetition.count) |k| { self.state.rollback(saved); self.state.translate(C.int(k) * repetition.dx, C.int(k) * repetition.dy); self.executeBody(repetition.body.items); } self.state.rollback(saved); } } } }
    fn executeCommand(self: *Renderer, command: *const Command) void { const execution = C.create(Execution, .{ .sequence = self.executions.items.len + 1, .layer = self.layers.items.len - 1, .command = command }); C.append(*Execution, &self.executions, execution); var arena = std.heap.ArenaAllocator.init(C.backing); defer arena.deinit(); const previous = C.scratch; C.scratch = arena.allocator(); defer C.scratch = previous;
        if (self.check(command)) |failure| { execution.kind = .failed; execution.failure = failure; return; } const tag = enumValue(Tag, command.keyword).?; if (stateCommand(tag)) { self.applyState(tag, command.args); return; } const pixels = self.draw(tag, command); execution.kind = .drawing; execution.pixels = pixels.count(); execution.box = pixels.box();
    }
    fn run(self: *Renderer) void { for (self.scene.layers.items) |block| { C.append(*C.Layer, &self.layers, C.create(C.Layer, C.Layer.init(self.scene.width, self.scene.height, block.opacity, block.mode))); self.state = .{ .clip = self.screen }; self.executeBody(block.body.items); } }
    fn vertices(self: *const Renderer, args: C.Strings) []const C.Point { const values = numbers(args[1..]); const result = C.tempAlloc(C.Point, values.len / 2); for (result, 0..) |*point, i| point.* = self.state.point(values[2 * i], values[2 * i + 1]); return result; }
    fn buildSubpaths(self: *const Renderer, commands: []const PathCommand, segments: usize) []const Subpath { var result: std.ArrayList(Subpath) = .empty; var current: C.Point = .{ .x = 0, .y = 0 }; var start = current;
        for (commands) |command| { const kind = upper(command.letter); if (kind == 'Z') { result.items[result.items.len - 1].closed = true; current = start; continue; } const relative = command.letter >= 'a' and command.letter <= 'z'; const ox = if (relative) current.x else 0; const oy = if (relative) current.y else 0; var points: [3]C.Point = undefined; var count: usize = 0;
            if (kind == 'H') { points[0] = .{ .x = command.values[0] + ox, .y = current.y }; count = 1; } else if (kind == 'V') { points[0] = .{ .x = current.x, .y = command.values[0] + oy }; count = 1; } else { count = command.count / 2; for (0..count) |i| points[i] = .{ .x = command.values[2 * i] + ox, .y = command.values[2 * i + 1] + oy }; } var device: [3]C.Point = undefined; for (points[0..count], device[0..count]) |point, *target| target.* = self.state.point(point.x, point.y);
            if (kind == 'M') { var path: Subpath = .{}; C.push(C.Point, &path.points, device[0]); C.push(Subpath, &result, path); start = points[0]; } else { const path = &result.items[result.items.len - 1]; if (kind == 'L' or kind == 'H' or kind == 'V') C.push(C.Point, &path.points, device[0]) else { var controls: [4]C.Point = undefined; controls[0] = path.points.items[path.points.items.len - 1]; @memcpy(controls[1..count + 1], device[0..count]); for (P.bezier(controls[0..count + 1], segments)[1..]) |point| C.push(C.Point, &path.points, point); } } current = points[count - 1];
        } return result.items;
    }
    fn stroke(self: *const Renderer, mask: C.Mask, pen: Pen, segments: []const C.Segment) void { var counter: i64 = 0; for (segments) |segment| { const clipped = K.segment(segment, self.state.clip) orelse continue; for (P.bresenham(clipped.first, clipped.last)) |point| { if (pen.off == 0 or @mod(counter, pen.on + pen.off) < pen.on) P.expand(mask, point, pen.width, self.state.clip); counter += 1; } } }
    fn shape(self: *const Renderer, tag: Tag, values: []const i64) struct { center: C.Point, points: []const C.Point } { const center = self.state.point(values[0], values[1]); const circle = tag == .CIRCLE or tag == .FILLCIRCLE; const radii = self.state.radii(values[2], if (circle) values[2] else values[3]); return .{ .center = center, .points = if (circle and radii.x == radii.y) P.circle(radii.x) else P.ellipse(radii.x, radii.y) }; }
    fn penCoverage(self: *const Renderer, mask: C.Mask, tag: Tag, pen: Pen, args: C.Strings) void {
        if (tag == .CIRCLE or tag == .ELLIPSE) { const outline = self.shape(tag, numbers(args)); for (outline.points) |point| P.expand(mask, .{ .x = outline.center.x + point.x, .y = outline.center.y + point.y }, pen.width, self.state.clip); return; }
        var segments: std.ArrayList(C.Segment) = .empty;
        switch (tag) { .LINE => { const values = numbers(args); C.push(C.Segment, &segments, .{ .first = self.state.point(values[0], values[1]), .last = self.state.point(values[2], values[3]) }); },
            .RECT => { const rect = self.state.rectangle(numbers(args)); const points = [_]C.Point{ .{ .x = rect.x0, .y = rect.y0 }, .{ .x = rect.x1, .y = rect.y0 }, .{ .x = rect.x1, .y = rect.y1 }, .{ .x = rect.x0, .y = rect.y1 } }; addSegments(&segments, &points, true); },
            .POLYLINE, .POLYGON => addSegments(&segments, self.vertices(args), tag == .POLYGON),
            .PATH => { const subpaths = self.buildSubpaths(parsePath(args[1..]).?, C.index(C.number(args[0]))); for (subpaths) |path| addSegments(&segments, path.points.items, path.closed); },
            else => unreachable,
        }
        self.stroke(mask, pen, segments.items);
    }
    fn textCoverage(self: *const Renderer, mask: C.Mask, x: i64, y: i64, alignment: []const u8, text: []const u8) void { const advance = self.font.width + 1; const extent = C.int(text.len) * advance - 1; const left = if (C.eq(alignment, "left")) x else if (C.eq(alignment, "center")) x - @divFloor(extent, 2) else x - extent + 1; for (text, 0..) |ch, i| { if (ch == '_') continue; const origin = left + C.int(i) * advance; for (self.font.glyphs.get(ch).?) |dot| { const first = self.state.point(origin + dot.x, y + dot.y); const last = self.state.point(origin + dot.x + 1, y + dot.y + 1); addRect(mask, .{ .x0 = @min(first.x, last.x), .y0 = @min(first.y, last.y), .x1 = @max(first.x, last.x) - 1, .y1 = @max(first.y, last.y) - 1 }, self.state.clip); } } }
    fn brushCoverage(self: *const Renderer, mask: C.Mask, tag: Tag, brush: Brush, args: C.Strings) void { switch (tag) {
        .FILLRECT => addRect(mask, self.state.rectangle(numbers(args)), self.state.clip),
        .FILLCIRCLE, .FILLELLIPSE => { const outline = self.shape(tag, numbers(args)); F.shape(mask, outline.center, outline.points, self.state.clip); },
        .FILLPOLYGON => { const sequence = K.polygon(self.vertices(args), self.state.clip); F.polygons(mask, &.{sequence}, brush.rule, self.state.clip); },
        .FILLPATH => { const subpaths = self.buildSubpaths(parsePath(args[1..]).?, C.index(C.number(args[0]))); const sequences = C.tempAlloc([]const C.Point, subpaths.len); for (subpaths, sequences) |path, *sequence| sequence.* = K.polygon(path.points.items, self.state.clip); F.polygons(mask, sequences, brush.rule, self.state.clip); },
        .FLOOD => F.flood(mask, self.layer(), self.state.point(C.number(args[0]), C.number(args[1])), self.state.clip),
        .TEXT => self.textCoverage(mask, C.number(args[0]), C.number(args[1]), args[2], args[3]), else => unreachable,
    } }
    fn draw(self: *Renderer, tag: Tag, command: *const Command) C.Mask { const mask = C.Mask.init(self.scene.width, self.scene.height); const args = command.args; if (tag == .ERASE) { const rect = self.state.rectangle(numbers(args)).intersect(self.state.clip); addRect(mask, rect, self.state.clip); const layer_value = self.layer(); for (mask.bits, 0..) |*value, i| { if (!value.*) continue; if (layer_value.colors[i] == null) value.* = false else layer_value.colors[i] = null; } return mask; }
        if (penCommand(tag)) { const pen = self.styles.pens.get(args[0]).?; self.penCoverage(mask, tag, pen, args[1..]); const color = self.styles.colors.get(pen.color).?; for (mask.bits, 0..) |value, pixel| { if (value) self.layer().paint(pixel, color, command.line); } } else { const brush = self.styles.brushes.get(args[0]).?; self.brushCoverage(mask, tag, brush, args[1..]); const first = self.styles.colors.get(brush.colors[0]).?; const box = mask.box(); for (mask.bits, 0..) |value, pixel| { if (!value) continue; const color = if (brush.axis) |axis| gradient(first, self.styles.colors.get(brush.colors[1]).?, axis, box.?, .{ .x = C.int(pixel % mask.width), .y = C.int(pixel / mask.width) }) else first; self.layer().paint(pixel, color, command.line); } } return mask;
    }
};
fn addSegments(result: *std.ArrayList(C.Segment), points: []const C.Point, closed: bool) void { if (points.len == 0) return; for (0..points.len - 1) |i| C.push(C.Segment, result, .{ .first = points[i], .last = points[i + 1] }); if (closed) C.push(C.Segment, result, .{ .first = points[points.len - 1], .last = points[0] }); }
fn addRect(mask: C.Mask, input: C.Rect, clip: C.Rect) void { const rect = input.intersect(clip); var y = rect.y0; while (y <= rect.y1) : (y += 1) { var x = rect.x0; while (x <= rect.x1) : (x += 1) mask.add(.{ .x = x, .y = y }, clip); } }
