fn layerLines(renderer: *const Renderer) C.Lines { const layers = renderer.layers.items; const visible = C.alloc(usize, layers.len); @memset(visible, 0); for (0..renderer.scene.width * renderer.scene.height) |pixel| { var covered = false; var i = layers.len; while (i > 0) { i -= 1; const alpha = layers[i].alpha(pixel); if (alpha > 0 and !covered) visible[i] += 1; if (alpha == 255) covered = true; } }
