fn symbolUses(renderer: *const Renderer) std.StringHashMapUnmanaged(usize) { var result: std.StringHashMapUnmanaged(usize) = .empty; for (sortedNames(renderer.scene.symbols)) |name| result.put(C.allocator, name, 0) catch @panic("allocation failed"); for (renderer.executions.items) |execution| { if (execution.kind == .state and C.eq(execution.command.keyword, "USE")) { const name = execution.command.args[0]; result.put(C.allocator, name, result.get(name).? + 1) catch @panic("allocation failed"); } } return result; }
