fn summaryLines(renderer: *const Renderer, image: []const C.RGB) C.Lines { const Tally = struct { executed: usize = 0, errors: usize = 0, pixels: usize = 0 }; var tallies: std.StringHashMapUnmanaged(Tally) = .empty; var drawing: usize = 0; var state: usize = 0; var errors: usize = 0; var error_counts = [_]usize{0} ** 7; var painted: usize = 0; var erased: usize = 0;
    for (renderer.executions.items) |execution| { const keyword = execution.command.keyword; var tally = tallies.get(keyword) orelse Tally{}; tally.executed += 1; switch (execution.kind) { .failed => { errors += 1; tally.errors += 1; error_counts[@intFromEnum(execution.failure.?)] += 1; }, .state => state += 1, .drawing => { drawing += 1; tally.pixels += execution.pixels; if (C.eq(keyword, "ERASE")) erased += execution.pixels else painted += execution.pixels; } } tallies.put(C.allocator, keyword, tally) catch @panic("allocation failed"); }
