    const reports = [_]C.Lines{ W.ppm(image, scene.width, scene.height), W.preview(image, scene.width, scene.height), commandLines(renderer.executions.items), layerLines(&renderer), summaryLines(&renderer, image), probeLines(probes, &renderer, image) }; const names = [_][]const u8{ "image.ppm", "preview.txt", "commands.txt", "layers.txt", "summary.txt", "probes.txt" }; try dir.createDirPath(init.io, "output"); for (names, reports) |name, report| try dir.writeFile(init.io, .{ .sub_path = C.fmt("output/{s}", .{name}), .data = report.content() });
}
